/** Word-level layout for plain app paragraphs whose short final line SwiftUI would rebalance. */
export declare const GREEDY_TEXT_RUNTIME = "\nstruct MarkswiftGreedyText: View {\n    let value: String\n    let font: Font\n    let color: Color\n    let fontSize: CGFloat\n    let lineGap: CGFloat\n\n    init(_ value: String, font: Font, color: Color, fontSize: CGFloat, lineGap: CGFloat) {\n        self.value = value\n        self.font = font\n        self.color = color\n        self.fontSize = fontSize\n        self.lineGap = lineGap\n    }\n\n    var body: some View {\n        let words = value.split(separator: \" \")\n        MarkswiftFlow(columnGap: fontSize * 0.25, rowGap: lineGap) {\n            ForEach(words.indices, id: \\.self) { index in\n                Text(verbatim: String(words[index]))\n                    .font(font)\n                    .foregroundStyle(color)\n            }\n        }\n        .accessibilityElement(children: .ignore)\n        .accessibilityLabel(value)\n    }\n}\n";
